type LugInput = {
  slug: string; keyword: string; make: string; model: string; title: string;
  torque: string; metric: string; scope: string; source: Source;
  context: string; caution: string; image?: "sedan" | "suv";
};

function editorialLug(input: LugInput): SpecRecord {
  const base: Base = {
    slug: input.slug,
    keyword: input.keyword,
    make: input.make,
    model: input.model,
    category: "Torque Specs",
    title: input.title,
    metaDescription: `${input.title}. Verified ${input.torque} (${input.metric}) factory-wheel value, star-pattern steps, dry-thread guidance, FAQs, and sources.`,
    answer: `For the factory-wheel application covered here, use ${input.torque} (${input.metric}). Tighten clean, dry fasteners in an opposite-side pattern and confirm the exact owner's manual when the wheel or hardware is not original.`,
    detail: `${input.context} The value is a final hand-torque setting, not an impact-wrench target.`,
    scope: input.scope,
    values: [
      { label: "Factory wheel torque", value: input.torque, note: input.metric },
      { label: "Fastener condition", value: "Clean and dry", note: "No oil or anti-seize unless the exact manual directs it" },
      { label: "Tightening method", value: "Star / opposite-side", note: "Hand-start, staged passes, calibrated torque wrench" },
      { label: "Verification", value: "Manual + hardware check", note: "Aftermarket wheels and fasteners may specify a different value" },
    ],
    sources: [input.source],
    identity: `${input.model} with factory wheel fasteners`,
    distinctions: [input.context, input.caution],
    featureImage: input.image === "sedan" ? lugSedan : lugSuv,
    featureOverlay: true,
  };
  const record = lugGuide(base);
  record.intro = [
    `${record.answer} That is the useful number, but it only produces a trustworthy installation when the wheel is fully seated and the friction conditions match the manual. Torque is a proxy for stud tension; rust, lubricant, damaged seats, or an impact gun can make the same wrench reading create a very different clamp load.`,
    `${input.context} This page is deliberately scoped to the named application instead of blending several generations into one chart. ${input.caution} If the vehicle has conversion studs, spacers, locking hardware, or aftermarket wheels, identify those parts before choosing a setting.`,
    "A careful wheel installation is repeatable: inspect, hand-start, snug across the wheel, apply the final setting smoothly, then make a confirmation pass. The diagram and checklist below turn the specification into a procedure a home mechanic or technician can actually audit.",
  ];
  record.sections.unshift({
    heading: `What matters specifically on the ${input.model}`,
    paragraphs: [
      `${input.context} The table keeps the published imperial and metric values together so a unit conversion never becomes a shop-floor guess. Use a socket that fully engages the fastener and a torque wrench whose normal working range comfortably includes ${input.torque}.`,
      `${input.caution} A wheel that rocks on corrosion, paint, or a mismatched seat can feel tight before it is clamped flat. Clean the hub pad and inspect every seat first; torque cannot correct a mechanical mismatch.`,
    ],
  });
  record.faqs[0] = { q: `What is the correct ${input.keyword}?`, a: `${input.torque} (${input.metric}) for the factory-wheel application described here. Confirm non-original wheels, fasteners, and trim-specific instructions separately.` };
  return record;
}

