accordSpark.sections.unshift({heading:"Start with the engine, not the badge", paragraphs:["An Accord search can refer to several unrelated four-cylinder and V6 families. Read the eighth VIN character where applicable, the emissions label, and the plug number removed from an unmodified engine. Then cross-check the approved Honda application before measuring anything.", "For a modern laser-iridium plug, consistency among a set matters, but aggressive regapping is the wrong quality-control method. Shipping damage, a crooked ground strap, or a chipped insulator calls for replacement."]});

type FiringInput = { slug:string; keyword:string; make:string; model:string; title:string; order:string; numbering:string; scope:string; context:string; caution:string; source:Source };
const researchedFiringEditorial:Record<string,{sections:SpecRecord["sections"];faqs:SpecRecord["faqs"]}>={
  "honda/j35/firing-order":{
    sections:[
      {heading:"The Honda diagram this page is anchored to",paragraphs:["Honda's 2025 warranty-extension bulletin for the 2013–2017 Odyssey includes an engine-view diagram that labels the rear, firewall-side bank as cylinders 1-2-3 and the front, radiator-side bank as 4-5-6. The same figure prints the firing order as 1-4-2-5-3-6. That makes this page an application-specific reference for the transverse Odyssey J35, not a promise that every vehicle ever fitted with a J35 presents the engine from the same viewing angle.","The bulletin also identifies the crankshaft-pulley side. That orientation marker matters because words such as left, right, front and rear can change meaning depending on whether a person is standing at the bumper or sitting in the vehicle. Start with the pulley side and the numbered banks shown by Honda; only then translate a scan-tool cylinder number into a physical coil, plug or injector." ]},
      {heading:"How to use the order during a misfire diagnosis",paragraphs:["A P0301 through P0306 code names a physical cylinder. It does not name that cylinder's position in the combustion sequence. For example, cylinder 4 is the first cylinder on the front bank in the covered Odyssey layout, even though it is the second event in 1-4-2-5-3-6. Record freeze-frame data and any companion fuel-trim or injector codes before clearing memory.","A careful coil-swap test changes one thing at a time. Label both coils, move the suspected coil to a known cylinder, clear the code only after recording it, and repeat the operating conditions that set the fault. If the misfire follows the coil, the result points toward the coil or its connection. If it stays on the original cylinder, continue with the plug, injector command, compression, valve clearance and mechanical checks rather than replacing an entire bank of parts." ]},
      {heading:"VCM and bank language without the common mix-ups",paragraphs:["Honda's Variable Cylinder Management strategy is one reason J35 searches often mention particular cylinders or a rear bank. VCM information is calibration- and vehicle-specific; it does not change the mechanical firing order or renumber the engine. Treat a VCM-related symptom, oil-consumption concern or bulletin as a separate diagnostic layer and confirm the exact VIN eligibility before applying it.","Bank 1 on the cited transverse layout is the firewall bank because that bank contains cylinder 1. Bank identity follows cylinder numbering—not the driver's seating position and not whichever side is easiest to reach. Oxygen-sensor bank labels, coil connector labels and physical cylinder numbers should all be checked against the same application diagram before parts are swapped." ]},
    ],
    faqs:[
      {q:"What is the firing order for the 2013–2017 Honda Odyssey 3.5L J35?",a:"Honda's application diagram lists 1-4-2-5-3-6."},
      {q:"Where is cylinder 1 on the covered Honda J35?",a:"It is on the rear/firewall-side bank. That bank contains cylinders 1-2-3; the front/radiator-side bank contains 4-5-6."},
      {q:"Does P0304 mean the fourth event in the firing order?",a:"No. P0304 identifies physical cylinder 4, which is the second combustion event in the 1-4-2-5-3-6 sequence."},
      {q:"Can I use this bank orientation for every Honda or Acura J35?",a:"Do not assume so. The order is well established, but installed orientation, suffix, wiring and service procedures must be confirmed for the exact vehicle and J35 variant."},
    ],
  },
  "volkswagen/2-0-tsi/firing-order":{
    sections:[
      {heading:"Exact application: 2014 Golf and GTI CBFA/CCTA",paragraphs:["Volkswagen's January 2014 Golf/GTI Quick Reference Specification Book identifies the 2.0L CBFA and CCTA engines and lists the ignition sequence as 1-3-4-2. The same table specifies a 1.0–1.1 mm spark-plug gap and 25 N·m plug torque, useful cross-checks when the task involves ignition service rather than firing-order identification alone.","This application boundary is important. '2.0 TSI' appears on several Volkswagen Group engine generations, while a 2.0L badge can also describe a naturally aspirated engine with different ignition hardware. Read the engine code from the vehicle data label or service information before ordering coils, plugs, injectors or timing components." ]},
      {heading:"Cylinder numbering and coil-on-plug diagnosis",paragraphs:["The four cylinders form one row, numbered 1-2-3-4 from the timing-drive end toward the transmission on the covered installation. The combustion events then occur 1-3-4-2. Because each plug has an individual coil, there is no distributor-cap tower sequence to rewire; the diagram's job is to connect a physical cylinder to scan data, coil connectors and component locations.","For a P030x complaint, save freeze-frame data and note whether P0300, fuel-pressure, cam/crank correlation or mixture codes are present. Inspect the plug well for oil or water, check the connector lock and harness strain, and use a controlled coil swap only when the parts are interchangeable. A misfire that remains on the same cylinder after a verified coil swap calls for plug, injector, compression, valve-train and intake-leak testing." ]},
      {heading:"EA888 generation boundaries matter",paragraphs:["Later EA888 Gen 3 technical data also uses 1-3-4-2, but that shared order does not make the engines service-identical. Timing-drive design, ignition parts, fuel-system pressure, sensor locations and repair procedures can change with engine code and model year. A correct firing-order page should help identify a cylinder without encouraging parts interchange across generations.","Do not rotate or disturb timing components merely to investigate crossed coils: the engine management system schedules spark electronically. If correlation codes or mechanical timing symptoms are present, move to the exact Volkswagen repair procedure for the engine code and use its locking tools, timing marks and torque stages." ]},
    ],
    faqs:[
      {q:"What is the firing order for a 2014 VW Golf or GTI 2.0 TSI CBFA/CCTA?",a:"Volkswagen lists the ignition sequence as 1-3-4-2."},
      {q:"Where is cylinder 1 on the covered VW 2.0 TSI?",a:"Cylinder 1 is at the timing-drive end of the inline engine; numbering continues 1-2-3-4 toward the transmission."},
      {q:"Does the VW 2.0 TSI have distributor wires to arrange?",a:"No. The covered CBFA/CCTA engines use coil-on-plug ignition. Use the order for cylinder identification and diagnosis, not for arranging cap towers."},
      {q:"Is every Volkswagen 2.0L engine covered by this diagram?",a:"No. Confirm the engine code. Other 2.0L gasoline engines and later EA888 generations may share the order while using different parts and procedures."},
    ],
  },
};
function editorialFiring(input:FiringInput):SpecRecord {
  const base:Base = {
    slug:input.slug, keyword:input.keyword, make:input.make, model:input.model, category:"Firing Order", title:input.title,
    metaDescription:`${input.model} firing order ${input.order}, cylinder numbering, interactive diagram, connector-routing notes, troubleshooting, FAQs, and official source links.`,
    answer:`The ${input.model} firing order is ${input.order}. ${input.numbering}`,
    detail:input.context, scope:input.scope,
    values:[
      {label:"Firing order", value:input.order, note:"One complete four-stroke combustion sequence"},
      {label:"Cylinder numbering", value:input.numbering, note:"Confirm orientation before moving wires or coils"},
      {label:"Diagnostic rule", value:"Identify before swapping", note:"Coil connector number and cylinder number are not interchangeable"},
    ],
    sources:[input.source], identity:input.model, distinctions:[input.context,input.caution], featureImage:firingImage, featureOverlay:true,
  };
  const record=firingGuide(base);
  const rows=[...input.numbering.matchAll(/(?:bank|side) (?:is|carries) ([0-9](?:[-–][0-9])*)/gi)].map((match)=>match[1].split(/[-–]/));
  const inline=input.numbering.match(/Cylinders (?:are |are numbered )?([0-9](?:[-–][0-9])*)/i);
  record.diagram.banks=rows.length ? rows : inline ? [inline[1].split(/[-–]/)] : undefined;
  record.diagram.engineLabel=input.model;
  record.diagram.orientation=input.numbering.split(".")[0];
  record.intro=[`${record.answer} The order is simple to print; the difficult part is applying it to the correct physical cylinders. ${input.context}`, `A firing-order diagram should answer three separate questions: which cylinder is which, what sequence the crankshaft uses, and how the ignition system reaches each cylinder. ${input.caution} The interactive drawing below keeps the order visible while the table preserves the numbering notes in crawlable text.`, "Before disconnecting anything, photograph the harness or leads, label both ends, and identify the engine from a durable source. That five-minute audit is faster than diagnosing a crossed pair after the engine has been reassembled."];
  record.sections.unshift({heading:`Reading the ${input.model} diagram correctly`, paragraphs:[`${input.numbering} Read the vehicle as installed and use the manufacturer's left/right convention, not the side from which you happen to be standing. The first cylinder listed in ${input.order} begins the sequence but does not define a universal connector position.`, `${input.context} ${input.caution} On coil-on-plug engines, use the diagram for cylinder identity and diagnosis; the PCM, not a physical distributor cap, schedules spark.`]});
  const editorial=researchedFiringEditorial[input.slug];
  if(editorial){record.sections.unshift(...editorial.sections);record.faqs=editorial.faqs;}
  return record;
}

